-- 导出  表 zsc.comment 结构
CREATE TABLE IF NOT EXISTS `comment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '评价ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `hotel_id` bigint NOT NULL COMMENT '酒店ID',
  `room_id` bigint DEFAULT NULL COMMENT '房型ID',
  `order_id` bigint DEFAULT NULL COMMENT '订单ID',
  `score` int NOT NULL COMMENT '评分（1-5星）',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '评价内容',
  `images` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '评价图片JSON数组',
  `img_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '图片URL',
  `is_anonymous` char(1) DEFAULT '0' COMMENT '是否匿名（0=否 1=是）',
  `status` char(1) DEFAULT '1' COMMENT '状态（0=待审核 1=已发布 2=已拒绝）',
  `like_count` int DEFAULT '0' COMMENT '点赞数',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `appeal_reason` varchar(500) DEFAULT NULL COMMENT '申诉理由',
  `appeal_time` datetime DEFAULT NULL COMMENT '申诉时间',
  `appeal_status` char(1) DEFAULT '0' COMMENT '申诉状态（0=无申诉 1=申诉中 2=通过 3=驳回）',
  `reply_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '回复内容',
  `reply_time` datetime DEFAULT NULL COMMENT '回复时间',
  `reply_by` bigint DEFAULT NULL COMMENT '回复人ID',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建者',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_hotel_id` (`hotel_id`) USING BTREE,
  KEY `idx_room_id` (`room_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=151 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='评价表';

